        LinearLayout root=new LinearLayout(activity);backgroundSurface=root;root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(12),dp(4),dp(12),dp(8));root.setBackground(new Drawable(){public void draw(Canvas canvas){background.setShader(new LinearGradient(0,0,getBounds().width(),getBounds().height(),new int[]{backgroundColor,0xff17151d,0xff101117},null,Shader.TileMode.CLAMP));canvas.drawRect(getBounds(),background);}public void setAlpha(int value){}public void setColorFilter(ColorFilter filter){}public int getOpacity(){return PixelFormat.OPAQUE;}});
        LinearLayout header=new LinearLayout(activity);header.setGravity(Gravity.CENTER_VERTICAL);PlayerIconButton close=icon(R.drawable.player_chevron_down,"收起播放页",false);header.addView(close,new LinearLayout.LayoutParams(dp(48),dp(48)));close.setOnClickListener(v->dismiss());source=label(11,0xffc6bece);source.setGravity(Gravity.CENTER);source.setSingleLine(true);header.addView(source,new LinearLayout.LayoutParams(0,dp(40),1));PlayerIconButton more=icon(R.drawable.player_ellipsis,"更多播放操作",false);header.addView(more,new LinearLayout.LayoutParams(dp(48),dp(48)));more.setOnClickListener(v->more(more));root.addView(header,new LinearLayout.LayoutParams(-1,dp(48)));
        body=new Body(activity);cover=new LyricsPlayerBody.Cover(activity);cover.setContentDescription("点按封面打开歌词，左右滑动切歌");cover.setClickable(true);cover.setOnClickListener(v->host.lyrics());installCoverGesture();body.addView(cover);
        LinearLayout panel=new LinearLayout(activity);panel.setOrientation(LinearLayout.VERTICAL);panel.setGravity(Gravity.CENTER_VERTICAL);panel.setPadding(dp(12),0,dp(12),0);
        LinearLayout nameRow=new LinearLayout(activity);nameRow.setGravity(Gravity.CENTER_VERTICAL);LinearLayout names=new LinearLayout(activity);names.setOrientation(LinearLayout.VERTICAL);title=label(22,0xfff3edf9);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);title.setSingleLine(true);artist=label(12,0xffbdb2ca);artist.setSingleLine(true);names.addView(title);LinearLayout.LayoutParams artistParams=new LinearLayout.LayoutParams(-1,dp(24));names.addView(artist,artistParams);nameRow.addView(names,new LinearLayout.LayoutParams(0,-2,1));favorite=icon(R.drawable.player_heart,"收藏歌曲",false);nameRow.addView(favorite,new LinearLayout.LayoutParams(dp(48),dp(48)));favorite.setOnClickListener(v->host.like());panel.addView(nameRow,new LinearLayout.LayoutParams(-1,dp(54)));
        detail=label(10,0xffa99ab8);detail.setSingleLine(true);detail.setOnClickListener(v->host.quality());panel.addView(detail,new LinearLayout.LayoutParams(-1,dp(22)));
        progress=new SeekBar(activity);progress.setContentDescription("播放页播放进度");progress.setMax(10000);progress.setPadding(dp(5),0,dp(5),0);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(0xffe1c6ff));progress.setSecondaryProgressTintList(android.content.res.ColorStateList.valueOf(0xff6c5d7d));progress.setProgressBackgroundTintList(android.content.res.ColorStateList.valueOf(0xff332d3d));progress.setThumbTintList(android.content.res.ColorStateList.valueOf(0xfff2e5ff));panel.addView(progress,new LinearLayout.LayoutParams(-1,dp(28)));installSeek();
        LinearLayout times=new LinearLayout(activity);elapsed=label(10,0xffb6a9c4);remaining=label(10,0xffb6a9c4);remaining.setGravity(Gravity.END);times.addView(elapsed,new LinearLayout.LayoutParams(0,dp(18),1));times.addView(remaining,new LinearLayout.LayoutParams(0,dp(18),1));panel.addView(times);
