        for(PlayerIconButton button:new PlayerIconButton[]{shuffle,previous,play,next,repeat}){LinearLayout.LayoutParams params=button==play?new LinearLayout.LayoutParams(dp(64),dp(64)):new LinearLayout.LayoutParams(0,dp(56),1);transport.addView(button,params);}panel.addView(transport,new LinearLayout.LayoutParams(-1,dp(68)));play.setOnClickListener(v->host.toggle());previous.setOnClickListener(v->host.previous());next.setOnClickListener(v->host.next());shuffle.setOnClickListener(v->{PlaybackService.Snapshot s=host.state();host.modes(!s.shuffle,s.repeat);refresh();});repeat.setOnClickListener(v->{PlaybackService.Snapshot s=host.state();host.modes(s.shuffle,!s.repeat);refresh();});
        LinearLayout shortcuts=new LinearLayout(activity);shortcuts.setGravity(Gravity.CENTER_VERTICAL);queue=icon(R.drawable.player_list_music,"播放队列",false);lyrics=icon(R.drawable.player_mic_vocal,"打开逐字歌词",false);quality=icon(R.drawable.player_sliders_horizontal,"播放音质与音效",false);queueLabel=label(10,0xffac9abb);LinearLayout queueGroup=new LinearLayout(activity);queueGroup.setGravity(Gravity.CENTER_VERTICAL);queueGroup.addView(queue,new LinearLayout.LayoutParams(dp(48),dp(48)));queueGroup.addView(queueLabel,new LinearLayout.LayoutParams(-2,-2));shortcuts.addView(queueGroup,new LinearLayout.LayoutParams(0,dp(48),1));shortcuts.addView(lyrics,new LinearLayout.LayoutParams(dp(48),dp(48)));shortcuts.addView(quality,new LinearLayout.LayoutParams(dp(48),dp(48)));panel.addView(shortcuts,new LinearLayout.LayoutParams(-1,dp(48)));queue.setOnClickListener(v->host.queue());queueLabel.setOnClickListener(v->host.queue());lyrics.setOnClickListener(v->host.lyrics());quality.setOnClickListener(v->host.quality());
