    int dp(float value){return (int)(value*getContext().getResources().getDisplayMetrics().density+.5f);}
    private TextView label(int size,int color){TextView view=new TextView(getContext());view.setTextSize(size);view.setTextColor(color);view.setGravity(Gravity.CENTER_VERTICAL);view.setEllipsize(TextUtils.TruncateAt.END);return view;}
    private PlayerIconButton icon(int resource,String description,boolean prominent){PlayerIconButton view=new PlayerIconButton(getContext(),resource,description,prominent);view.motion=!reduceMotion;return view;}
    private static void text(TextView view,String value){if(!value.contentEquals(view.getText()))view.setText(value);}
    private String artists(JSONObject track){if(track==null)return "";JSONArray values=track.optJSONArray("artists");StringBuilder result=new StringBuilder();if(values!=null)for(int i=0;i<Math.min(3,values.length());i++){String name=values.optJSONObject(i)==null?values.optString(i):values.optJSONObject(i).optString("name");if(!name.isEmpty()){if(result.length()>0)result.append(" / ");result.append(name);}}return result.length()>0?result.toString():track.optString("artist","");}
    void refresh(){
        PlaybackService.Snapshot state=host.state();if(state==null)return;String selected=state.uri;boolean changed=!selected.equals(uri);
        if(changed){uri=selected;artwork=null;backgroundColor=0xff292333;backgroundSurface.invalidate();cover.setArtwork(null);favoriteAvailable=host.canLike(uri);text(source,host.source(state));if(touching)cancelled=true;}
        String name=state.track==null?state.title:state.track.optString("name",state.title);text(title,name.isEmpty()?"尚未选择歌曲":name);title.setContentDescription(name);String author=artists(state.track);text(artist,author.isEmpty()?"未知艺术家":author);
        String status=!state.error.isEmpty()?state.error:state.loading?"正在准备音频":state.buffering&&state.playing?"正在缓冲":state.qualitySwitching?"正在准备新音质，原音频继续播放":state.playing?"正在播放":"已暂停";text(detail,status+" · "+state.qualityInfo.replace('\n',' '));detail.setContentDescription(detail.getText());
        Bitmap current=host.artwork(selected);if(current!=artwork){artwork=current;cover.setArtwork(current);if(current!=null&&!current.isRecycled()){int pixel=current.getPixel(current.getWidth()/2,current.getHeight()/2);backgroundColor=Color.rgb((Color.red(pixel)+35)/4,(Color.green(pixel)+28)/4,(Color.blue(pixel)+50)/4);backgroundSurface.invalidate();}if(!reduceMotion&&current!=null){cover.setAlpha(.45f);cover.animate().alpha(1).setDuration(240).start();}}
        play.icon(state.playing?R.drawable.player_pause:R.drawable.player_play);play.describe(state.loading?"暂停或继续准备音频":state.playing?"暂停播放":"开始播放");shuffle.setChecked(state.shuffle);shuffle.describe(state.shuffle?"随机播放：开":"随机播放：关");repeat.icon(state.repeat?R.drawable.player_repeat_1:R.drawable.player_repeat);repeat.setChecked(state.repeat);repeat.describe(state.repeat?"单曲循环":"列表循环");favorite.setChecked(host.liked(uri));boolean pending=host.likePending(uri);favorite.setEnabled(favoriteAvailable&&!pending&&!uri.isEmpty());favorite.describe(pending?"正在保存收藏":!favoriteAvailable?"此来源未提供收藏接口":host.liked(uri)?"取消收藏歌曲":"收藏歌曲");
        text(queueLabel,state.queueSize+" 首");queue.describe("播放队列，共 "+state.queueSize+" 首");progress.setEnabled(state.ready&&state.duration>0);if(!touching){progress.setProgress(state.duration>0?(int)Math.min(10000,state.position*10000L/state.duration):0);showTime(state.position,state.duration);}progress.setSecondaryProgress(Math.max(0,Math.min(100,state.buffered))*100);
    }
    private void showTime(int position,int duration){text(elapsed,format(position));text(remaining,duration>0?"−"+format(Math.max(0,duration-position)):"直播或时长未知");}
    private static String format(long value){value=Math.max(0,value);return value>=3600000?String.format(java.util.Locale.CHINA,"%d:%02d:%02d",value/3600000,value/60000%60,value/1000%60):String.format(java.util.Locale.CHINA,"%02d:%02d",value/60000,value/1000%60);}
    private boolean sameSeek(){PlaybackService.Snapshot state=host.state();return state!=null&&state.ready&&seekGeneration==state.generation&&seekUri.equals(state.uri);}
    private void installSeek(){
        progress.setOnTouchListener((view,event)->{if(event.getActionMasked()==MotionEvent.ACTION_DOWN)cancelled=false;else if(event.getActionMasked()==MotionEvent.ACTION_CANCEL)cancelled=true;return false;});progress.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar bar){PlaybackService.Snapshot state=host.state();touching=true;seekGeneration=state.generation;seekUri=state.uri;seekDuration=state.duration;preview=(int)(seekDuration*bar.getProgress()/10000L);}public void onProgressChanged(SeekBar bar,int value,boolean user){if(!user)return;if(touching){preview=(int)(seekDuration*value/10000L);showTime(preview,seekDuration);}else{PlaybackService.Snapshot state=host.state();if(state.ready&&state.duration>0)host.seek((int)(state.duration*value/10000L));}}public void onStopTrackingTouch(SeekBar bar){boolean commit=touching&&!cancelled&&seekDuration>0&&sameSeek();touching=false;if(commit)host.seek(preview);refresh();}});
    }
    private void installCoverGesture(){
        cover.setOnTouchListener(new View.OnTouchListener(){float x,y;long generation;String selected;boolean horizontal,vertical;public boolean onTouch(View view,MotionEvent event){int action=event.getActionMasked();if(action==MotionEvent.ACTION_DOWN){x=event.getX();y=event.getY();PlaybackService.Snapshot state=host.state();generation=state.generation;selected=state.uri;horizontal=false;vertical=false;return true;}float dx=event.getX()-x,dy=event.getY()-y;if(action==MotionEvent.ACTION_MOVE){int slop=ViewConfiguration.get(getContext()).getScaledTouchSlop();if(!horizontal&&!vertical&&Math.max(Math.abs(dx),Math.abs(dy))>slop){horizontal=Math.abs(dx)>Math.abs(dy)*1.4;vertical=!horizontal;}if(horizontal&&!reduceMotion)cover.setTranslationX(Math.max(-dp(32),Math.min(dp(32),dx*.18f)));return true;}if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL){PlaybackService.Snapshot state=host.state();boolean current=state.generation==generation&&state.uri.equals(selected);boolean swipe=action==MotionEvent.ACTION_UP&&horizontal&&Math.abs(dx)>Math.max(dp(64),cover.getWidth()*.23f)&&Math.abs(dy)<dp(64)&&current;if(reduceMotion)cover.setTranslationX(0);else cover.animate().translationX(0).setDuration(180).start();if(swipe){if(dx<0)host.next();else host.previous();}else if(action==MotionEvent.ACTION_UP&&!horizontal&&!vertical&&current)view.performClick();return true;}return true;}});
    }
    private void more(View anchor){PopupMenu menu=new PopupMenu(getContext(),anchor);String[] names={"音效与均衡器","定时暂停","播放音量","歌曲评论"};for(int i=0;i<names.length;i++)menu.getMenu().add(0,i,i,names[i]);if(host.devices())menu.getMenu().add(0,4,4,"远程播放设备");menu.getMenu().findItem(0).setIcon(R.drawable.player_sliders_horizontal);menu.getMenu().findItem(1).setIcon(R.drawable.player_moon);menu.getMenu().findItem(2).setIcon(R.drawable.player_volume_2);if(Build.VERSION.SDK_INT>=29)menu.setForceShowIcon(true);menu.setOnMenuItemClickListener(item->{switch(item.getItemId()){case 0:host.effects();break;case 1:host.sleep();break;case 2:host.volume();break;case 3:host.comments();break;case 4:host.showDevices();break;}return true;});menu.show();}
    @Override public void onWindowFocusChanged(boolean hasFocus){super.onWindowFocusChanged(hasFocus);handler.removeCallbacks(tick);if(hasFocus&&isShowing())handler.post(tick);}
    @Override public void dismiss(){handler.removeCallbacksAndMessages(null);body.animate().cancel();cover.animate().cancel();cover.release();super.dismiss();}
    @Override protected void onStop(){handler.removeCallbacksAndMessages(null);super.onStop();}
    final class Body extends ViewGroup {
        Body(Context context){super(context);}
        void exact(View child,int w,int h){child.measure(MeasureSpec.makeMeasureSpec(Math.max(1,w),MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(Math.max(1,h),MeasureSpec.EXACTLY));}
        @Override protected void onMeasure(int widthSpec,int heightSpec){int w=MeasureSpec.getSize(widthSpec),h=MeasureSpec.getSize(heightSpec);setMeasuredDimension(w,h);boolean split=w>=dp(520)&&w>h*1.3f;View art=getChildAt(0),controls=getChildAt(1);if(split){int album=Math.min((int)(w*.42f),h);art.setVisibility(VISIBLE);exact(art,album-dp(24),album-dp(24));exact(controls,w-album,h);}else if(h>=dp(490)){int side=Math.min(w-dp(56),h-dp(276));art.setVisibility(VISIBLE);exact(art,side,side);exact(controls,w,dp(252));}else{art.setVisibility(GONE);exact(controls,w,h);}}
        @Override protected void onLayout(boolean changed,int l,int t,int r,int b){int w=r-l,h=b-t;View art=getChildAt(0),controls=getChildAt(1);boolean split=w>=dp(520)&&w>h*1.3f;if(split){int album=Math.min((int)(w*.42f),h),side=art.getMeasuredWidth();art.layout((album-side)/2,(h-side)/2,(album+side)/2,(h+side)/2);controls.layout(album,0,w,h);}else if(art.getVisibility()==VISIBLE){int side=art.getMeasuredWidth();art.layout((w-side)/2,dp(8),(w+side)/2,dp(8)+side);controls.layout(0,h-controls.getMeasuredHeight(),w,h);}else controls.layout(0,0,w,h);}
    }
